import { ChatList } from "@/components/Chat";

interface ChatPageProps {
    params: Promise<{
        chatId: string;
    }>;
}

export default async function ChatPage(props: ChatPageProps) {
    const params = await props.params;

    return (
        <div className="flex flax-1 flex-col h-full">
            <div className="p-4 border-b">
                <h1 className="text-lg font-bold">Chat {params.chatId}</h1>
            </div>
            <div className="flex-1 p-4">
                {/* Logic to load specific chat messages will go here */}
                <p className="text-muted-foreground">Displaying chat thread: {params.chatId}</p>
            </div>
        </div>
    );
}
